import {ERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";

/// @title Super IMD
/// @notice Super IMD ERC-20. Ticker: SIMD. Fixed supply: the entire supply is minted in the constructor.
///         Website: https://www.si-md.xyz/
///         Twitter / X: https://x.com/SuperIMD_eth
///         Normal transfers have no fee. Swap fees (sell antisniper, etc.) are charged only
///         through the Uniswap v4 hook (see SIMDhook.sol).
contract SuperIMD is ERC20, ERC20Permit {
    constructor(uint256 initialSupply, address recipient)
        ERC20("Super IMD", "SIMD")
        ERC20Permit("Super IMD")
    {
        _mint(recipient, initialSupply);
    }
}

