pragma solidity ^0.8.26;

import {BaseHook} from "./base/BaseHook.sol";
import {Hooks} from "v4-core/src/libraries/Hooks.sol";
import {IHooks} from "v4-core/src/interfaces/IHooks.sol";
import {IPoolManager} from "v4-core/src/interfaces/IPoolManager.sol";
import {PoolKey} from "v4-core/src/types/PoolKey.sol";
import {BalanceDelta} from "v4-core/src/types/BalanceDelta.sol";
import {Currency} from "v4-core/src/types/Currency.sol";
import {SwapParams} from "v4-core/src/types/PoolOperation.sol";
import {SafeCast} from "v4-core/src/libraries/SafeCast.sol";

/// @title SuperIMDHook
/// @notice Uniswap v4 hook for Super IMD / SIMD.
///         Website: https://www.si-md.xyz/
///         Twitter / X: https://x.com/SuperIMD_eth
///         Immutable 2% fee on every swap (buy and sell). Cannot be changed.
///         Works for ETH or IMD quote tokens.
contract SuperIMDHook is BaseHook {
    using SafeCast for uint256;

    uint256 public constant FEE_BIPS = 200;
    uint256 public constant TOTAL_BIPS = 10_000;

    address public immutable feeRecipient;
    address public immutable projectToken;

    error ZeroAddress();

    constructor(IPoolManager _manager, address _feeRecipient, address _projectToken) BaseHook(_manager) {
        if (_feeRecipient == address(0) || _projectToken == address(0)) revert ZeroAddress();
        feeRecipient = _feeRecipient;
        projectToken = _projectToken;
    }

    function getHookPermissions() public pure override returns (Hooks.Permissions memory) {
        return Hooks.Permissions({
            beforeInitialize: false,
            afterInitialize: false,
            beforeAddLiquidity: false,
            afterAddLiquidity: false,
            beforeRemoveLiquidity: false,
            afterRemoveLiquidity: false,
            beforeSwap: false,
            afterSwap: true,
            beforeDonate: false,
            afterDonate: false,
            beforeSwapReturnDelta: false,
            afterSwapReturnDelta: true,
            afterAddLiquidityReturnDelta: false,
            afterRemoveLiquidityReturnDelta: false
        });
    }

    function _afterSwap(
        address,
        PoolKey calldata key,
        SwapParams calldata params,
        BalanceDelta delta,
        bytes calldata
    ) internal override returns (bytes4, int128) {
        (Currency feeCurrency, int128 unspecifiedAmount) = (params.amountSpecified < 0 == params.zeroForOne)
            ? (key.currency1, delta.amount1())
            : (key.currency0, delta.amount0());

        if (unspecifiedAmount < 0) unspecifiedAmount = -unspecifiedAmount;

        uint256 feeAmount = (uint128(unspecifiedAmount) * FEE_BIPS) / TOTAL_BIPS;
        if (feeAmount == 0) return (IHooks.afterSwap.selector, 0);

        poolManager.take(feeCurrency, feeRecipient, feeAmount);
        return (IHooks.afterSwap.selector, feeAmount.toInt128());
    }
}


